s32 update_npc_dialogue(struct Moby         *moby,
                        struct SceneTrigger *trigger) __asm__("FUN_L00_00266448");

s32 update_npc_dialogue(struct Moby *moby, struct SceneTrigger *trigger) {
    struct Hero       *hero_ptr = &hero;
    struct SceneEntry *entry;
    s32                index;
    s32                handle;

    if (hero_ptr->state.current == 0x1D)
        return 0;
    if (hero_ptr->health.hp == 0)
        return 0;
    if (trigger->initialised == 0)
        FUN_L00_002668a0_c(moby, trigger);
    if (D_L00_0015F5C4 != 0)
        return 0;
    if (trigger == 0)
        return 0;
    if (trigger->entry == -1)
        return 0;
    if (trigger->any_direction == 0xFF)
        return 0;
    if (fast_vec_dist(&moby->pos, &hero_ptr->motion.pos) > trigger->radius + trigger->radius)
        return 0;

    process_menu_entry(moby, trigger, 0);

    if (trigger->any_direction == 0) {
        /* the moby must face the hero ... */
        if (fast_difference_between_rotations(fast_arc_tan(hero_ptr->motion.pos.f[0] - moby->pos.x,
                                                           hero_ptr->motion.pos.f[1] - moby->pos.y),
                                              moby->rot.z) > trigger->radius)
            return 0;
        /* ... and the hero the moby, within 1.57 (about 90 degrees) */
        if (fast_difference_between_rotations(fast_arc_tan(moby->pos.x - hero_ptr->motion.pos.f[0],
                                                           moby->pos.y - hero_ptr->motion.pos.f[1]),
                                              hero_ptr->motion.rot.f[2]) > 1.57f)
            return 0;
    }

    if (game_frame < active_scene_trigger.next_frame)
        return 0;

    if (trigger->any_direction != 0 || (D_0013CAE4[0] & 0x10)) {
        index = FUN_L00_002667d0_c2(moby);
        if (level_object_states[index].state == 0)
            level_object_states[index].state = 1;
        active_scene_trigger.moby = moby;
        active_scene_trigger.trigger = trigger;

        entry = &trigger->entries[trigger->entry];
        if (entry->flags & 8) {
            if (entry->cost_kind == 1)
                current_bolt_count -= D_L00_001C40B0[entry->cost_id].f0;
            else if (entry->cost_kind == 4)
                alternate_item_available[entry->cost_id] = 0;
        }
        if (entry->scene == -1) {
            process_menu_entry(moby, trigger, 1);
            return 1;
        }

        /* stored again: retail repeats the two stores here */
        active_scene_trigger.moby = moby;
        active_scene_trigger.trigger = trigger;
        if (entry->scene & 0x4000) {
            queue_scene_movie_with_game_language((s16)(entry->scene ^ 0x4000));
            return 1;
        }
        remove_hud_item(bolt_hud_item);
        bolt_hud_item = -1;
        start_scene(entry->scene);
        return 1;
    }

    if (hud_keep_visible(bolt_hud_item, 10)) {
        bolt_hud_item = queue_animation_update(
            12, 0, initialize_numeric_hud_element, mine_blend_color, draw_hud_text_panel, 0, 0);
    }
    {
        /* a fresh block-local pointer (not `entry`) keeps retail's registers */
        struct SceneEntry *unpaid = &trigger->entries[trigger->entry];

        if (unpaid->cost_kind == 1 || unpaid->cost_kind == 6) {
            handle = queue_animation_update(2,
                                            0x754E,
                                            initialize_bolt_counter_hud,
                                            update_bolt_counter_hud_animation_and_visibility,
                                            draw_bolt_counter_hud_panel,
                                            &current_bolt_count,
                                            9999999);
            hud_keep_visible(handle, scale_game_frames(60));
        }
    }
    return 0;
}

